import{_ as i,a0 as p,w as u,s as a,ao as l,I as n,x as o,a1 as s,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"一项研究显示，谷歌在开源贡献方面超过了微软 | LCTT x X-CMD","titleTemplate":false,"description":"一项研究显示，谷歌在开源贡献方面超过了微软 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一项研究显示，谷歌在开源贡献方面超过了微软 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一项研究显示，谷歌在开源贡献方面超过了微软 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220818 Google Surpasses Microsoft In Terms Of Open Source Contributors, Says A Study","title":"一项研究显示，谷歌在开源贡献方面超过了微软","tag":"202208","desc":""},"relativePath":"202208/20220818 Google Surpasses Microsoft In Terms Of Open Source Contributors, Says A Study.md","filePath":"[post].md"}'),f={name:"202208/20220818 Google Surpasses Microsoft In Terms Of Open Source Contributors, Says A Study.md"};function d(m,t,T,S,C,g){const e=p("Link");return u(),a("div",null,[t[15]||(t[15]=l('<h1 id="一项研究显示-谷歌在开源贡献方面超过了微软" tabindex="-1">一项研究显示，谷歌在开源贡献方面超过了微软 <a class="header-anchor" href="#一项研究显示-谷歌在开源贡献方面超过了微软" aria-label="Permalink to “一项研究显示，谷歌在开源贡献方面超过了微软”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/08/coding-new-1536x864.jpg" alt=""></p><blockquote><p>根据 Aiven 的一份新报告，谷歌已经提高了其对开源软件的投入，并在活跃贡献者方面超过了微软。</p></blockquote><p>根据 Aiven 的报告（LCTT 译注：我没有找到这份报告），谷歌目前的活跃贡献者多于微软，这要归功于对开源代码库 GitHub 的每月提交量同比增长 20%。根据开源贡献者指数（OCSI）的数据，谷歌 7 月份有 5421 名活跃贡献者，而微软的活跃贡献者为 5268 名。</p><p>Aiven 联合创始人兼首席技术官 Heikki Nousiainen 说，谷歌超过微软“特别令人惊讶”。</p><p>“这其中的一个因素是微软对开源项目的提交逐年下降，”Nousiainen 说，“然而，微软对开发者自由和创新的投入是一致的，该公司是开源的主要参与者，甚至在 2018 年收购了 GitHub。”</p><p>Aiven 指出，亚马逊已经开始更加重视开源计划，其对 OpenSearch（ElasticSearch 的复刻）的支持以及 GitHub 上项目数量的增加就是证明。Nousiainen 认为，亚马逊对 OpenSearch 和 ElasticSearch 的支持代表了“该公司方向的重大改变”，以及对重大开源项目掌舵的愿望。据 Aiven 介绍，这些科技巨头正在迅速扩大对开源软件的使用。根据数据，现在来自亚马逊、微软和谷歌的活跃 GitHub 贡献者比六年前多了 300%。</p><p>“这项研究的总体信息是积极的，”Nousiainen 说，“在开源社区有大量的创新在继续发生，其结果使我们所有人受益。数不清的人正在为其他人树立一个榜样。”</p><hr>',9)),n("p",null,[t[1]||(t[1]=o("via: ",-1)),s(e,{href:"https://www.opensourceforu.com/2022/08/google-surpasses-microsoft-in-terms-of-open-source-contributors-says-a-study/"},{default:r(()=>[...t[0]||(t[0]=[o("https://www.opensourceforu.com/2022/08/google-surpasses-microsoft-in-terms-of-open-source-contributors-says-a-study/",-1)])]),_:1})]),n("p",null,[t[6]||(t[6]=o("作者：",-1)),s(e,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:r(()=>[...t[2]||(t[2]=[o("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=o(" 选题：",-1)),s(e,{href:"https://github.com/lkxed"},{default:r(()=>[...t[3]||(t[3]=[o("lkxed",-1)])]),_:1}),t[8]||(t[8]=o(" 译者：",-1)),s(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[4]||(t[4]=[o("wxy",-1)])]),_:1}),t[9]||(t[9]=o(" 校对：",-1)),s(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[5]||(t[5]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=o("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[10]||(t[10]=[o("LCTT",-1)])]),_:1}),t[13]||(t[13]=o(" 原创编译，",-1)),s(e,{href:"https://linux.cn/"},{default:r(()=>[...t[11]||(t[11]=[o("Linux中国",-1)])]),_:1}),t[14]||(t[14]=o(" 荣誉推出",-1))])])}const y=i(f,[["render",d]]);export{b as __pageData,y as default};
